draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // book
  ctx.fillStyle = '#663300';
  ctx.fillRect(W/2-50, H/2-50, 100, 10);
  ctx.fillRect(W/2-20, H/2-70, 40, 40);

  // stick figure
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/2, H/2+50, 20, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2+30);
  ctx.lineTo(W/2, H/2+70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2+50);
  ctx.lineTo(W/2-30, H/2+30);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2+50);
  ctx.lineTo(W/2+30, H/2+30);
  ctx.stroke();

  // applying wisdom
  ctx.beginPath();
  ctx.moveTo(W/2, H/2+70);
  ctx.lineTo(W/2+50+30*Math.sin(t), H/2+100);
  ctx.stroke();

  // lesson life
  ctx.font = '20px Arial';
  ctx.textAlign = 'left';
  ctx.textBaseline = 'top';
  ctx.fillStyle = 'black';
  ctx.fillText('Lesson:', W/2-70, H/2-120);
  ctx.fillText('Life:', W/2-70, H/2-90);

  // numbers
  ctx.font = '30px Arial';
  ctx.textAlign = 'left';
  ctx.textBaseline = 'top';
  ctx.fillStyle = 'black';
  ctx.fillText('859', W/2-30, H/2-60+20*Math.sin(t));

  ctx.restore();
}
